package com.iridium126.createmanaindustry.content.allaystorm;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class StormV10Test {
 @Test void independentClocksConsumeFailedAndSkippedOpportunities(){var s=new MajorAttackSchedule();assertFalse(s.due(2,100,30));assertFalse(s.due(1,100,30));assertFalse(s.due(2,699,30));assertTrue(s.due(2,700,30));assertTrue(s.due(1,700,30));assertFalse(s.due(2,700,30));assertTrue(s.due(2,5000,30));assertFalse(s.due(2,5000,30));assertEquals(List.of(0,1,2,0),java.util.stream.IntStream.range(0,4).map(i->s.first()).boxed().toList());}
 @Test void opportunitiesRotateEvenWhenIntervalsAreMultiplesOfThree(){var s=new MajorAttackSchedule();s.due(2,0,30);s.due(1,0,30);for(int i=1;i<=6;i++){assertTrue(s.ready(i*600));assertEquals((i-1)%3,s.first());assertTrue(s.due(2,i*600,30));assertTrue(s.due(1,i*600,30));assertFalse(s.ready(i*600));}for(int i=0;i<6;i++){assertEquals(i%3,s.target(2,3));assertEquals(i%3,s.target(1,3));}}
 @Test void exactThresholdsAndRealOppositeArms(){var dead=new BitSet();var reserved=new BitSet();assertEquals(0,AllayHelix.select(16383,dead,reserved,4096,123,0).members().length);var a=AllayHelix.select(16384,dead,reserved,4096,123,0);assertEquals(4096,a.members().length);assertArrayEquals(new int[]{2048,4096},a.ends());dead.set(16383);assertEquals(0,AllayHelix.select(16384,dead,reserved,4096,123,0).members().length);
  dead.clear();int[] available=new int[6];for(int i=0;i<131072;i++){int arm=AllayHelix.arm(123,i);if((arm==0||arm==3)&&available[arm]++<2048)continue;reserved.set(i);}assertEquals(4096,AllayHelix.select(131072,dead,reserved,4096,123,0).members().length);
  for(int i=0;i<131072;i++)if(!reserved.get(i)&&AllayHelix.arm(123,i)==3){reserved.set(i);break;}assertEquals(0,AllayHelix.select(131072,dead,reserved,4096,123,0).members().length);
 }
 @Test void fixedTemplateEnvelopeAndMeshClearance(){assertTrue(HelixTemplate.available());for(int i=0;i<4096;i++){double x=HelixTemplate.coordinate(i,0),y=HelixTemplate.coordinate(i,1),z=HelixTemplate.coordinate(i,2),u=(32-x)/64;assertTrue(u>=0&&u<=1);assertTrue(Math.hypot(y,z)<=.6*Math.pow(32/.6,u)+.0001);for(int j=0;j<i;j++){double a=x-HelixTemplate.coordinate(j,0),b=y-HelixTemplate.coordinate(j,1),c=z-HelixTemplate.coordinate(j,2);assertTrue(a*a+b*b+c*c>=1.43999);}}}
 @Test void threeDimensionalAxisAndBoundedTurn(){var v=new net.minecraft.world.phys.Vec3(0,-1,0);var r=new AllayHelix.Selection(0,3,new int[4096],new int[]{2048,4096});var f=AllayHelix.linearFlight(r,new net.minecraft.world.phys.Vec3(500,200,-900),v,100,12,30);assertEquals(1,AllayHelix.axis(f).dot(v),.00001);assertEquals(30,f.thrust());var t=AllayHelix.turn(v,new net.minecraft.world.phys.Vec3(0,1,0),Math.toRadians(2));assertEquals(Math.toRadians(2),Math.acos(v.dot(t)),.000001);}
 @Test void farCoordinateFlightKeepsUnitAxis(){var axis=new net.minecraft.world.phys.Vec3(.2,-.7,.4).normalize();var roster=new AllayHelix.Selection(0,3,new int[4096],new int[]{2048,4096});var flight=AllayHelix.linearFlight(roster,new net.minecraft.world.phys.Vec3(-28000000,100,29000000),axis,100,12,30);assertEquals(1,axis.dot(AllayHelix.axis(flight)),.0000001);}
 @Test void completionCodecKeepsHighRanksAndIdentity(){var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),net.minecraft.core.RegistryAccess.EMPTY,net.neoforged.neoforge.network.connection.ConnectionType.OTHER);try{var bits=new BitSet();bits.set(0);bits.set(4095);var p=new com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackCompletedPacket(net.minecraft.world.level.Level.OVERWORLD.location(),88,123,bits.toLongArray());var codec=com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackCompletedPacket.STREAM_CODEC;codec.encode(b,p);var q=codec.decode(b);assertEquals(p.dimension(),q.dimension());assertEquals(p.epoch(),q.epoch());assertArrayEquals(p.ranks(),q.ranks());assertFalse(b.isReadable());}finally{b.release();}}
 @Test void spatialPlayersAreNotTruncatedAndReuseStorage(){var grid=new com.iridium126.createmanaindustry.client.allaystorm.StormPlayerGrid();float[] xyz=new float[300];for(int i=0;i<100;i++){xyz[i*3]=i%2==0?-i*7:i*7;xyz[i*3+1]=i;xyz[i*3+2]=i*2;}grid.build(xyz,100);var data=grid.data();int table=(int)data[400],found=0;var seen=new BitSet();for(int h=0;h<table;h++){int head=(int)data[(101+h)*4+3];while(head>0){assertFalse(seen.get(head-1));seen.set(head-1);found++;head=(int)data[(head-1)*4+3];}}assertEquals(100,found);grid.build(xyz,100);assertSame(data,grid.data());}
}
